<?php\n// modules/finance/payroll/settings/GLMappingForm.php - Handles POST requests for saving mappings.\n\n/**\n * This file is included by index.php when a mapping is submitted.\n * It validates inputs and calls DbUtility to save the record.\n *\n* NOTE: This assumes $dbUtil (an instance of Finance\\Core\\DbUtility) is available in scope.\n*/\n\n// Placeholder for error handling context variables (These should be set by index.php):\n// if (!isset($error_message)) $error_message = null;\n// if (!isset($success_message)) $success_message = null;\n\nfunction handleMappingSave(\PDO $pdo, &$dbUtil) {\n    if ($_SERVER['REQUEST_METHOD'] !== 'POST' || !isset($_POST['payroll_component']) || !isset($_POST['chart_account_id'])) {\n        return ['success' => false, 'message' => 'Invalid request method or missing fields.'];\n    }\n\n    $payload = [\n        'payroll_component' => trim($_POST['payroll_component']), // e.g., Basic Salary\n        'chart_account_id' => trim($_POST['chart_account_id']),   // GL Account ID\n        'mapping_type' => $_POST['mapping_type'],                 // Expense, Payable\n    ];\n\n    if (empty($payload['payroll_component']) || empty($payload['chart_account_id'])) {\n        return ['success' => false, 'message' => 'Both Payroll Component and GL Account ID are required.'];\n    }\n    \n    $sql = \"INSERT INTO payroll_finance_mappings (payroll_component, chart_account_id, mapping_type, status) VALUES (:comp, :acct, :type, 'ACTIVE');\";\n    $params = [\n        ':comp' => $payload['payroll_component'],\n        ':acct' => $payload['chart_account_id'],\n        ':type' => $payload['mapping_type']\n    ];\n\n    if ($dbUtil->execute($sql, $params)) {\n        return ['success' => true, 'message' => \"Mapping successfully saved for '{$payload['payroll_component']}' to account '{$payload['chart_account_id']}'.\"];\n    } else {\n        // This catches errors from the underlying DbUtility::execute method.\n        return ['success' => false, 'message' => \"Database error occurred while saving mapping. Check logs for details.\"];\n    }\n}\n\n// --- Execution Context ---\n// We need to pass $dbUtil and the global PDO object (or mock it) into this scope.\n// Since we are simulating include/require includes, we will assume the calling script passes necessary variables.\n\n// For demonstration purposes in a real environment, you would call:\n// \$result = handleMappingSave(\$pdo, \$dbUtil);\n// echo json_encode(\$result); // Or redirect based on result\n\n// Placeholder return for structural review: \n// If running this file directly, it will fail, but structure is set.\n?>"